package TushCodes;

public class LoopBreakDemo {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		
		for(int i=1 ; i<=10 ; i++) {
			
			if(i==7)
				break; //It stop the loop at an fixed value of i
			           // and iterate the loop required no.of times
			System.out.println(i);
		}
	}

}
